/* OCAF039: deliberately minimal static Linux x86_64 guest init.
 * Launched only in throwaway CI Firecracker guest with readonly rootfs.
 * Sends self-identifying UDP packet to a local host TAP address, never internet.
 * TENANT_NO and PROBE_NONCE are generated by the bounded test harness.
 */
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <fcntl.h>
#include <linux/if.h>
#include <net/if.h>
#include <netinet/in.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

#ifndef TENANT_NO
#error "TENANT_NO is required"
#endif
#ifndef PROBE_NONCE
#error "PROBE_NONCE is required"
#endif
#if TENANT_NO == 1
#define GUEST_IP "198.19.38.2"
#define HOST_IP "198.19.38.1"
#define PORT 23011
#define TENANT "A"
#elif TENANT_NO == 2
#define GUEST_IP "198.19.38.6"
#define HOST_IP "198.19.38.5"
#define PORT 23012
#define TENANT "B"
#else
#error "Invalid TENANT_NO"
#endif

static int set_ip(int s) {
    struct ifreq ifr = {0};
    struct sockaddr_in sin = {0};
    memcpy(ifr.ifr_name, "eth0", 5);
    sin.sin_family = AF_INET;
    if (inet_pton(AF_INET, GUEST_IP, &sin.sin_addr) != 1) return -1;
    memcpy(&ifr.ifr_addr, &sin, sizeof(sin));
    if (ioctl(s, SIOCSIFADDR, &ifr) < 0) return -1;
    if (inet_pton(AF_INET, "255.255.255.252", &sin.sin_addr) != 1) return -1;
    memcpy(&ifr.ifr_netmask, &sin, sizeof(sin));
    if (ioctl(s, SIOCSIFNETMASK, &ifr) < 0) return -1;
    if (ioctl(s, SIOCGIFFLAGS, &ifr) < 0) return -1;
    ifr.ifr_flags |= IFF_UP | IFF_RUNNING;
    return ioctl(s, SIOCSIFFLAGS, &ifr);
}

int main(void) {
    int console = open("/dev/console", O_WRONLY | O_NOCTTY);
    if (console >= 0)
        dprintf(console, "OCAF039_GUEST_NETWORK_INIT_TENANT_%s\\n", TENANT);
    int s = socket(AF_INET, SOCK_DGRAM | SOCK_CLOEXEC, 0);
    if (s < 0) goto out;
    /* Virtio-net enumeration may lag the init exec. */
    for (unsigned int k = 0; k < 100; k++) {
        if (set_ip(s) == 0) break;
        struct timespec t = {0, 100000000L};
        nanosleep(&t, NULL);
    }
    struct sockaddr_in destination = {0};
    destination.sin_family = AF_INET;
    destination.sin_port = htons(PORT);
    if (inet_pton(AF_INET, HOST_IP, &destination.sin_addr) != 1) goto out;
    struct timespec t = {0, 100000000L};
    for (unsigned int i = 0; i < 500; i++) {
        char msg[128] = {0};
        int n = snprintf(msg, sizeof(msg), "OCAF039:%s:%s:%u", TENANT, PROBE_NONCE, i);
        if (n > 0 && n < (int)sizeof(msg))
            (void)sendto(s, msg, (size_t)n, 0,
                         (struct sockaddr *)&destination, sizeof(destination));
        nanosleep(&t, NULL);
    }
out:
    if (s >= 0) close(s);
    /* PID 1 must not exit: otherwise kernel panics and corrupts the test. */
    for (;;) pause();
}
